import{b as a,O as e,g as i,j as l}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"测试风险识别与应对","description":"","frontmatter":{},"headers":[],"relativePath":"testing/risk/risk-management/index.md","filePath":"测试理论与实践/5.风险管理与拓展/16.测试风险识别与应对.md","lastUpdated":1781625968000}'),n={name:"testing/risk/risk-management/index.md"};function o(r,t,s,d,h,u){return e(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="测试风险识别与应对" tabindex="-1">测试风险识别与应对 <a class="header-anchor" href="#测试风险识别与应对" aria-label="Permalink to &quot;测试风险识别与应对&quot;">​</a></h1><blockquote><p>测试不是在真空中进行的——需求会变、时间会不够、环境会挂、人会请假。识别这些风险并提前准备应对方案，是测试能力从&quot;会测&quot;到&quot;靠谱&quot;的分界线。</p></blockquote><h2 id="测试中常见的六大风险" tabindex="-1">测试中常见的六大风险 <a class="header-anchor" href="#测试中常见的六大风险" aria-label="Permalink to &quot;测试中常见的六大风险&quot;">​</a></h2><h3 id="_1-需求变更" tabindex="-1">1. 需求变更 <a class="header-anchor" href="#_1-需求变更" aria-label="Permalink to &quot;1. 需求变更&quot;">​</a></h3><p><strong>表现</strong>：产品需求在开发甚至测试过程中发生变化，已有的测试用例需要修改或作废，刚跑通的自动化可能第二天就挂了。</p><p><strong>应对</strong>：</p><ul><li>用例和需求之间保持可追溯的关联——需求改了，能快速定位哪些用例受影响</li><li>用可执行的验收测试（Q2 活文档）替代静态用例文档——需求变了改对应的 scenario，跑一遍就知道受影响的点</li><li>需求变更本身需要有管理流程——不是&quot;产品群里说了一句&quot;，而是有记录、有评估、有通知</li></ul><h3 id="_2-时间压力" tabindex="-1">2. 时间压力 <a class="header-anchor" href="#_2-时间压力" aria-label="Permalink to &quot;2. 时间压力&quot;">​</a></h3><p><strong>表现</strong>：开发延期，测试时间被压缩到迭代最后两三天。这是最常见的风险，也是最容易导致&quot;赶工上线、出事回滚&quot;的根因。</p><p><strong>应对</strong>：</p><ul><li>测试活动从迭代第一天就开始（<a href="/testing/engineering/agile-testing-1.html">敏捷测试（上）</a>的迭代节奏），不等开发提测</li><li>优先测核心流程和高风险区域，而不是按用例编号顺序测</li><li>自动化回归套件是时间压缩时最重要的底气——自动化跑一遍等于几十个小时的手工回归</li><li>时间确实不够时做风险驱动的取舍（<a href="/testing/engineering/agile-testing-2.html">敏捷测试（下）</a>），坦率声明残留风险而不是假装都测完了</li></ul><h3 id="_3-环境问题" tabindex="-1">3. 环境问题 <a class="header-anchor" href="#_3-环境问题" aria-label="Permalink to &quot;3. 环境问题&quot;">​</a></h3><p><strong>表现</strong>：测试环境和生产环境不一致，导致测试结果不可靠——&quot;测试环境没问题，上线就炸&quot;。或者测试环境不稳定、经常不可用，测试人员被环境问题浪费大量时间。</p><p><strong>应对</strong>：</p><ul><li>用容器化（Docker）和基础设施即代码（IaC）把环境配置版本化、可复制化</li><li>尽可能让测试环境接近生产——同样的数据库版本、同样的中间件配置</li><li>对测试环境做定期校验：跑一组基准测试确认环境正常</li><li>如果环境不稳定是常态，把这个问题上升为团队级问题——不是测试的事，是整个交付流程的事</li></ul><h3 id="_4-人员问题" tabindex="-1">4. 人员问题 <a class="header-anchor" href="#_4-人员问题" aria-label="Permalink to &quot;4. 人员问题&quot;">​</a></h3><p><strong>表现</strong>：测试团队人手不足、经验欠缺、或者关键人员突然离开。一个人的知识变成单点风险。</p><p><strong>应对</strong>：</p><ul><li>测试用例写清楚到&quot;另一个人拿到手就能执行&quot;——降低对特定人员的依赖</li><li>交叉探索（<a href="/testing/engineering/agile-testing-2.html">敏捷测试（下）</a>）：不同的人测不同的模块，让知识在团队中流动</li><li>测试笔记和会话记录不只是给自己看——它们是团队的知识资产</li><li>培训不只是&quot;新员工入职培训&quot;——定期的技术分享、结对测试都是能力建设</li></ul><h3 id="_5-工具和技术" tabindex="-1">5. 工具和技术 <a class="header-anchor" href="#_5-工具和技术" aria-label="Permalink to &quot;5. 工具和技术&quot;">​</a></h3><p><strong>表现</strong>：选用的测试工具不稳定、不适合当前项目、或者团队不熟悉导致学习成本过高。自动化框架选错了，后期迁移成本巨大。</p><p><strong>应对</strong>：</p><ul><li>选工具前做小范围验证（PoC），而不是看完文档就决定</li><li>优先选社区活跃、文档完善的工具——出了问题能搜到答案</li><li>不追求&quot;最新最热&quot;——稳定的工具比新潮的工具更适合生产环境</li><li>团队里至少有一个对工具底层足够了解的人，能解决&quot;文档上没写&quot;的问题</li></ul><h3 id="_6-沟通问题" tabindex="-1">6. 沟通问题 <a class="header-anchor" href="#_6-沟通问题" aria-label="Permalink to &quot;6. 沟通问题&quot;">​</a></h3><p><strong>表现</strong>：开发、测试、产品之间的信息不对称——开发改了一个接口没通知测试、产品加了一个需求测试不知道、测试发现了问题开发觉得不是 bug。</p><p><strong>应对</strong>：</p><ul><li>建立信息同步机制：不是&quot;发了邮件就算通知了&quot;，而是确认对方收到了</li><li>Bug Council（<a href="/testing/execution/bug-management.html">缺陷管理</a>就是信息对齐的标准方式——有问题三方一起看，不靠中间人传话</li><li>测试人员主动参与需求讨论和站会——不等别人通知，自己去获取信息</li><li>跨角色协作不是&quot;搞好关系&quot;，是建立流程（<a href="/testing/engineering/agile-testing-2.html">敏捷测试（下）</a>）</li></ul><h2 id="风险管理不是-列个表" tabindex="-1">风险管理不是&quot;列个表&quot; <a class="header-anchor" href="#风险管理不是-列个表" aria-label="Permalink to &quot;风险管理不是&quot;列个表&quot;&quot;">​</a></h2><p>上面六条是常见风险，但真正的风险管理不只是列个清单。它在项目管理方法论中是一个闭环：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>风险识别 → 风险评估 → 风险应对 → 风险监控</span></span>
<span class="line"><span> (找出来)   (排优先级)  (定方案)    (持续跟踪)</span></span></code></pre></div><h3 id="识别-不只是靠经验" tabindex="-1">识别：不只是靠经验 <a class="header-anchor" href="#识别-不只是靠经验" aria-label="Permalink to &quot;识别：不只是靠经验&quot;">​</a></h3><p>除了凭经验&quot;觉得哪里可能出问题&quot;，有几种系统性的识别方法：</p><ul><li>回顾历史项目的测试报告和事故报告——上次在哪个环节出过问题</li><li>在测试计划阶段做一次专门的风险讨论——不只是测试人员参加，开发和产品也要在场</li><li>每一个&quot;如果 xxxx 怎么办&quot;的问题，就是一个风险项</li></ul><h3 id="评估-不是所有风险都值得应对" tabindex="-1">评估：不是所有风险都值得应对 <a class="header-anchor" href="#评估-不是所有风险都值得应对" aria-label="Permalink to &quot;评估：不是所有风险都值得应对&quot;">​</a></h3><p>对每个识别出的风险，问两个问题：</p><ul><li><strong>概率</strong>：发生的可能性多大？（高/中/低）</li><li><strong>影响</strong>：如果发生了，对测试的影响多大？（高/中/低）</li></ul><p>概率 × 影响 = 风险等级。精力优先放在&quot;高概率 × 高影响&quot;的风险上，&quot;低概率 × 低影响&quot;的风险记录下来但不需要专门制定应对方案。</p><h3 id="应对-四种基本策略" tabindex="-1">应对：四种基本策略 <a class="header-anchor" href="#应对-四种基本策略" aria-label="Permalink to &quot;应对：四种基本策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>做什么</th><th>举例</th></tr></thead><tbody><tr><td><strong>规避</strong></td><td>消除风险发生的条件</td><td>需求频繁变更 → 和产品约定迭代内不允许变更</td></tr><tr><td><strong>减轻</strong></td><td>降低概率或影响</td><td>时间压力 → 引入自动化回归，缩短测试周期</td></tr><tr><td><strong>转移</strong></td><td>把风险转给更适合应对的一方</td><td>安全漏洞 → 引入第三方渗透测试</td></tr><tr><td><strong>接受</strong></td><td>知道风险存在但选择不应对</td><td>&quot;如果地震了数据中心就挂了&quot;——概率极低，预案成本极高，接受它</td></tr></tbody></table><h3 id="监控-风险不是定一次就忘" tabindex="-1">监控：风险不是定一次就忘 <a class="header-anchor" href="#监控-风险不是定一次就忘" aria-label="Permalink to &quot;监控：风险不是定一次就忘&quot;">​</a></h3><p>每次迭代回顾会上，扫一眼风险列表：</p><ul><li>之前识别的高风险发生了吗？应对措施有效吗？</li><li>有没有新的风险冒出来？</li><li>低概率风险有没有变成高概率？</li></ul><blockquote><p>风险管理的目的不是消除所有风险——不可能。目的是<strong>不让应该预见到的问题变成意外</strong>。</p></blockquote><h3 id="两种不同的风险" tabindex="-1">两种不同的风险 <a class="header-anchor" href="#两种不同的风险" aria-label="Permalink to &quot;两种不同的风险&quot;">​</a></h3><p>到这里有一个重要的区分：前面讲的六种风险属于<strong>项目管理风险</strong>——什么会威胁测试进度。但测试策略中还有一种风险是<strong>产品质量风险</strong>——软件的哪部分最可能出问题、出问题后果最严重。两大类风险要分开看：</p><table tabindex="0"><thead><tr><th>类别</th><th>问什么问题</th><th>影响什么</th><th>应对方式</th></tr></thead><tbody><tr><td><strong>项目管理风险</strong></td><td>需求变了怎么办？时间不够怎么办？</td><td>测试能不能按计划完成</td><td>制定预案、调整资源、提前沟通</td></tr><tr><td><strong>产品质量风险</strong></td><td>哪个模块最可能出 bug？哪个功能挂了损失最大？</td><td>测试测什么、测多深</td><td>基于风险分配测试精力</td></tr></tbody></table><p>前面六节覆盖了项目管理风险。下面讲产品质量风险如何指导测试。</p><h2 id="基于风险确定测试优先级" tabindex="-1">基于风险确定测试优先级 <a class="header-anchor" href="#基于风险确定测试优先级" aria-label="Permalink to &quot;基于风险确定测试优先级&quot;">​</a></h2><p>既然不能穷举测试（<a href="/testing/basics/what-is-testing.html">重新认识软件测试</a>的结论），那有限的测试精力投到哪里？答案是：<strong>风险最高的地方。</strong></p><p>这个理念来自《软件测试的艺术》的核心策略——测试不是在所有模块上平均分配时间，而是把 80% 的精力投到风险最高的 20% 的模块上。</p><h3 id="如何评估产品质量风险" tabindex="-1">如何评估产品质量风险 <a class="header-anchor" href="#如何评估产品质量风险" aria-label="Permalink to &quot;如何评估产品质量风险&quot;">​</a></h3><p>对每个功能模块或需求，问三个问题：</p><table tabindex="0"><thead><tr><th>维度</th><th>问什么</th><th>高分信号</th></tr></thead><tbody><tr><td><strong>技术复杂度</strong></td><td>这段代码有多复杂？</td><td>多层嵌套逻辑、多线程、涉及分布式事务</td></tr><tr><td><strong>业务影响</strong></td><td>这里挂了损失多大？</td><td>涉及金钱、用户数据、核心转化路径</td></tr><tr><td><strong>历史数据</strong></td><td>这里以前出过多少问题？</td><td>该模块过去三个版本发现过 5+ 个 bug</td></tr></tbody></table><p>三点都高的模块 = 最高风险 → 测试最深入、用例最完整。三点都低的模块 = 低风险 → 保证基本可用就行，资源留给高风险区域。</p><h3 id="风险驱动的测试策略" tabindex="-1">风险驱动的测试策略 <a class="header-anchor" href="#风险驱动的测试策略" aria-label="Permalink to &quot;风险驱动的测试策略&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高风险模块（支付、安全、核心流程）：完整测试覆盖，条件覆盖+路径覆盖，多轮探索</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>中风险模块（搜索、列表、表单）：等价类+边界值+有限探索</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>低风险模块（关于我们、帮助页、静态协议）：基本功能验证，轻量回归</span></span></code></pre></div><p>这套分层和《探索式测试》的章程设计一脉相承：<strong>噩梦头条本质就是找出&quot;产品质量风险最高的地方&quot;</strong>——你最怕什么出事，就是在识别什么风险最高。章程的方向就是风险的指向。</p><p>在这个框架下，前面各章的实践也是风险工具：</p><ul><li><a href="/testing/execution/regression-release.html">回归测试与上线标准</a>的爬-走-跑灰度发布 → 发布风险管理</li><li><a href="/testing/methodology/security-testing.html">安全测试与渗透测试</a>的安全测试分层 → 安全风险管理</li><li><a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a>的部署管道 → 用自动化的分层闸门管理不同级别的质量风险</li><li><a href="/testing/engineering/agile-testing-1.html">敏捷测试（上）</a>的四象限中 Q3 和 Q4 → 分别覆盖业务风险和技术风险</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>风险分两类：项目管理风险（需求、时间、环境、人员、工具、沟通）和产品质量风险（复杂度、业务影响、历史数据）——分别影响&quot;测试能不能做完&quot;和&quot;测试测什么&quot;</li><li>项目管理风险用闭环管理：识别 → 评估（概率×影响）→ 应对（规避/减轻/转移/接受）→ 监控</li><li>产品质量风险用风险驱动测试策略：高风险模块（支付、安全、核心流程）最深入，低风险模块保基本可用</li><li>噩梦头条、爬走跑、管道、四象限——前面各章的实践本质上都是风险管理工具</li></ol>`,61)])])}const c=a(n,[["render",o]]);export{p as __pageData,c as default};
